Salmos 67 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que o salmista pede que Deus faça resplandecer sobre o seu povo?","o":["O seu rosto","A sua espada","O seu trono","A sua arca"],"c":0,"v":1,"e":"No versículo 1 o salmista pede: \"faça resplandecer sobre nós o seu rosto\"."},
 {"t":"multipla","p":"O salmista pede a bênção de Deus para que se conheça na terra o quê?","o":["A tua lei","O teu caminho","O teu templo","A tua cidade"],"c":1,"v":2,"e":"O versículo 2 diz: \"para que se conheça na terra o teu caminho\"."},
 {"t":"multipla","p":"Quem o salmista deseja que louve a Deus?","o":["Somente os sacerdotes","Somente os reis","Todos os povos","Somente os anciãos"],"c":2,"v":3,"e":"No versículo 3 ele diz: \"que todos os povos te louvem\"."},
 {"t":"multipla","p":"Por que as nações devem se alegrar e exultar?","o":["Porque os inimigos foram vencidos","Porque o templo foi reconstruído","Porque a chuva voltou a cair","Porque Deus julgará os povos com equidade"],"c":3,"v":4,"e":"O versículo 4 explica: \"pois julgarás os povos com equidade\"."},
 {"t":"multipla","p":"O que o salmo diz que a terra fez?","o":["Deu os seus frutos","Tremeu diante de Deus","Ficou seca","Abriu-se ao meio"],"c":0,"v":6,"e":"O versículo 6 diz: \"a terra deu os seus frutos\"."},
 {"t":"cv","p":"O salmista pede que a salvação de Deus seja conhecida apenas em Israel.","c":false,"v":2,"e":"O versículo 2 pede que a salvação de Deus seja conhecida \"entre todas as nações\"."},
 {"t":"cv","p":"O salmo diz que Deus governará as nações sobre a terra.","c":true,"v":4,"e":"O versículo 4 afirma que Deus \"governará as nações sobre a terra\"."},
 {"t":"cv","p":"No fim do salmo, diz-se que todos os confins da terra temerão a Deus.","c":true,"v":7,"e":"O versículo 7 diz que \"todos os confins da terra o temerão\"."}
]}

Salmos 68 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Com o que o salmista compara os ímpios que perecem na presença de Deus?","o":["Cera que se derrete diante do fogo","Palha levada pelo vento","Neve que derrete ao sol","Água que escorre na areia"],"c":0,"v":2,"e":"O versículo 2 diz que, assim como a cera se derrete diante do fogo, os ímpios perecem na presença de Deus."},
 {"t":"multipla","p":"Segundo o salmo, Deus em sua santa morada é pai de quem?","o":["Dos estrangeiros","Dos pobres","Dos órfãos","Dos reis"],"c":2,"v":5,"e":"O versículo 5 chama Deus de \"pai dos órfãos e juiz das viúvas\"."},
 {"t":"multipla","p":"O que aconteceu quando Deus avançou pelo deserto à frente do seu povo?","o":["O mar se abriu e o povo passou","A terra tremeu e os céus gotejaram","Caiu maná do céu sobre o povo","Uma coluna de fogo iluminou a noite"],"c":1,"v":8,"e":"O versículo 8 diz que a terra tremeu, os céus gotejaram e até o Sinai se abalou diante de Deus."},
 {"t":"multipla","p":"O Senhor está no meio dos seus carros assim como esteve em qual monte?","o":["Carmelo","Sião","Horebe","Sinai"],"c":3,"v":17,"e":"O versículo 17 diz que o Senhor está no meio dos carros \"assim como esteve no Sinai no lugar santo\"."},
 {"t":"multipla","p":"Na procissão de Deus no santuário, quem ia à frente?","o":["Os sacerdotes","Os cantores","As moças com adufes","Os tocadores de instrumentos de corda"],"c":1,"v":25,"e":"O versículo 25 diz que os cantores iam à frente, os tocadores de cordas atrás e as moças com adufes no meio."},
 {"t":"cv","p":"Benjamim, o mais jovem, aparece à frente dos príncipes de Judá.","c":true,"v":27,"e":"O versículo 27 diz: \"Ali está o mais jovem, Benjamim, à frente dos príncipes de Judá\"."},
 {"t":"cv","p":"O salmo diz que príncipes virão da Babilônia.","c":false,"v":31,"e":"O versículo 31 diz que os príncipes virão do Egito, e não da Babilônia."},
 {"t":"cv","p":"No fim do salmo, o Deus de Israel é apresentado como quem dá força e poder ao seu povo.","c":true,"v":35,"e":"O versículo 35 diz que o Deus de Israel é quem dá força e poder ao seu povo."}
]}

Salmos 51 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Segundo o quê o salmista pede que Deus se compadeça dele?","o":["Segundo a benignidade de Deus","Segundo os seus próprios méritos","Segundo a lei de Moisés","Segundo a fé de seus pais"],"c":0,"v":1,"e":"No versículo 1 ele pede: \"Compadece-te de mim, ó Deus, segundo a tua benignidade\"."},
 {"t":"multipla","p":"Contra quem o salmista diz que pecou?","o":["Contra o seu próximo","Contra o povo de Israel","Contra Deus somente","Contra os sacerdotes"],"c":2,"v":4,"e":"No versículo 4 ele diz: \"Contra ti, contra ti somente pequei\"."},
 {"t":"multipla","p":"Com o que o salmista pede para ser purificado?","o":["Com azeite","Com hissopo","Com fogo","Com sangue de cordeiro"],"c":1,"v":7,"e":"No versículo 7 ele pede: \"Purifica-me com hissopo, e ficarei limpo\"."},
 {"t":"multipla","p":"O que o salmista pede que Deus crie nele?","o":["Um coração puro","Uma língua sábia","Um reino forte","Uma descendência numerosa"],"c":0,"v":10,"e":"No versículo 10 ele pede: \"Cria em mim, ó Deus, um coração puro\"."},
 {"t":"multipla","p":"O que o salmista diz que fará depois que Deus lhe restituir a alegria da salvação?","o":["Construirá um novo altar","Oferecerá mil novilhos","Jejuará por quarenta dias","Ensinará aos transgressores os caminhos de Deus"],"c":3,"v":13,"e":"No versículo 13 ele diz: \"Então, ensinarei aos transgressores os teus caminhos\"."},
 {"t":"cv","p":"O salmista pede que Deus não lhe tire o Seu Santo Espírito.","c":true,"v":11,"e":"No versículo 11 ele pede: \"nem me tires o Teu Santo Espírito\"."},
 {"t":"cv","p":"O salmista afirma que Deus se deleita em holocaustos mais do que em um espírito quebrantado.","c":false,"v":16,"e":"No versículo 16 ele diz que Deus não se deleita em holocaustos, e no versículo 17, que o sacrifício a Deus é um espírito quebrantado."},
 {"t":"cv","p":"Perto do fim do salmo, o salmista pede que Deus edifique os muros de Jerusalém.","c":true,"v":18,"e":"No versículo 18 ele pede: \"Faze bem a Sião [...]; edifica os muros de Jerusalém\"."}
]}

Salmos 59 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Segundo o salmista, o que ele fez para merecer as ciladas dos poderosos?","o":["Nada, não cometeu transgressão nem pecado","Traiu a confiança deles","Falou mentiras contra eles","Fugiu da cidade"],"c":0,"v":3,"e":"No versículo 3, o salmista diz que os poderosos se reúnem contra ele sem que tenha cometido transgressão ou pecado."},
 {"t":"multipla","p":"Ao anoitecer, os inimigos são comparados a quê?","o":["Leões que rugem no deserto","Lobos que caçam nos campos","Cães que uivam à volta da cidade","Serpentes escondidas no caminho"],"c":2,"v":6,"e":"O versículo 6 diz que, ao anoitecer, eles uivam como cães à volta da cidade."},
 {"t":"multipla","p":"O que o salmista diz que está nos lábios dos inimigos?","o":["Mel","Espadas","Veneno","Fogo"],"c":1,"v":7,"e":"O versículo 7 afirma que há espadas nos lábios deles."},
 {"t":"multipla","p":"Qual será a reação do Senhor diante desses inimigos?","o":["Ficará em silêncio","Chorará por eles","Fará aliança com eles","Se rirá deles"],"c":3,"v":8,"e":"No versículo 8, o salmista diz que o Senhor se rirá deles e zombará de todas as nações."},
 {"t":"multipla","p":"Por que o salmista pede que Deus não mate os inimigos?","o":["Para que eles se arrependam","Para que o povo dele não se esqueça","Para que sirvam como escravos","Para que voltem à sua terra"],"c":1,"v":11,"e":"O versículo 11 diz: não os mates, para que meu povo não se esqueça."},
 {"t":"cv","p":"O salmista quer que os inimigos saibam que Deus reina em Jacó até os confins da terra.","c":true,"v":13,"e":"Isso está no versículo 13, logo depois do pedido para que Deus os consuma na sua indignação."},
 {"t":"cv","p":"No fim do salmo, o salmista pede que os inimigos sejam afastados e nunca mais voltem à cidade.","c":false,"v":14,"e":"No versículo 14, ele diz que voltem ao anoitecer e uivem como cães, cercando a cidade."},
 {"t":"cv","p":"Pela manhã, o salmista diz que louvará com alegria a misericórdia de Deus.","c":true,"v":16,"e":"O versículo 16 diz que pela manhã ele louvará com alegria a misericórdia de Deus, seu alto refúgio no dia da angústia."}
]}

Salmos 71 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Que imagem o salmista usa ao pedir que Deus seja seu acolhimento?","o":["Uma rocha habitável","Um rio de águas vivas","Uma torre de vigia","Uma tenda no deserto"],"c":0,"v":3,"e":"No começo do salmo, ele pede que Deus seja para ele uma rocha habitável, onde sempre encontre acolhimento."},
 {"t":"multipla","p":"Desde quando o salmista diz confiar em Deus?","o":["Desde que foi ungido rei","Desde a sua mocidade","Desde que voltou do exílio","Desde que venceu os inimigos"],"c":1,"v":5,"e":"Ele diz que sua confiança em Deus vem desde a mocidade, quando chama Deus de sua esperança."},
 {"t":"multipla","p":"O que os inimigos dizem a respeito do salmista?","o":["Que ele fugiu para o deserto","Que ele mentiu ao povo","Que Deus o desamparou","Que ele perdeu o trono"],"c":2,"v":11,"e":"Os inimigos conspiram dizendo que Deus o desamparou e que ninguém pode livrá-lo."},
 {"t":"multipla","p":"Por que o salmista pede a Deus que não o desampare na velhice?","o":["Para ver o templo reconstruído","Para vencer os inimigos em batalha","Para deixar herança aos filhos","Para anunciar a força de Deus a esta geração"],"c":3,"v":18,"e":"Já velho e de cabelos brancos, ele pede para não ser desamparado até anunciar a força de Deus a esta geração e o seu poder às que virão."},
 {"t":"multipla","p":"Com quais instrumentos o salmista promete louvar a Deus?","o":["Saltério e harpa","Trombeta e címbalos","Flauta e tamborim","Lira e trombeta"],"c":0,"v":22,"e":"Perto do fim, ele promete louvar com o saltério e cantar com a harpa ao Santo de Israel."},
 {"t":"cv","p":"O salmista afirma que sabe exatamente quantos são os feitos da salvação de Deus.","c":false,"v":15,"e":"Ele diz que proclamará os feitos da salvação de Deus, ainda que não saiba o seu número."},
 {"t":"cv","p":"O salmista diz que Deus, que o fez ver muitas angústias e males, ainda lhe restaurará a vida.","c":true,"v":20,"e":"Ele confia que Deus lhe restaurará a vida e de novo o tirará das profundezas da terra."},
 {"t":"cv","p":"No fim do salmo, o salmista diz que os seus inimigos continuam triunfando sobre ele.","c":false,"v":24,"e":"O último versículo diz que os que buscam o mal contra ele estão envergonhados e confundidos."}
]}

Salmos 69 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"No começo do salmo, até onde o salmista diz que as águas lhe sobem?","o":["Até os joelhos","Até à alma","Até a cintura","Até o pescoço"],"c":1,"v":1,"e":"No versículo 1, ele diz que as águas lhe sobem até à alma."},
 {"t":"multipla","p":"Com o que o salmista compara o número dos que o odeiam sem motivo?","o":["Com a areia do mar","Com as estrelas do céu","Com os fios de cabelo da sua cabeça","Com as folhas das árvores"],"c":2,"v":4,"e":"No versículo 4, ele diz que são mais numerosos do que os fios de cabelo da sua cabeça."},
 {"t":"multipla","p":"O que o salmista diz que o consumiu?","o":["O zelo pela casa de Deus","O medo dos inimigos","A tristeza pelos irmãos","A fome do jejum"],"c":0,"v":9,"e":"No versículo 9, ele diz que o zelo pela casa de Deus o consumiu."},
 {"t":"multipla","p":"Quem fazia canções sobre o salmista?","o":["Os sacerdotes","Os seus irmãos","Os reis vizinhos","Os bêbados"],"c":3,"v":12,"e":"No versículo 12, ele diz que é motivo de canções para os bêbados."},
 {"t":"multipla","p":"De onde o salmista pede a Deus que o retire para que ele não afunde?","o":["Da prisão","Do lamaçal","Do deserto","Da cova dos leões"],"c":1,"v":14,"e":"No versículo 14, ele pede: retira-me do lamaçal para que eu não afunde."},
 {"t":"cv","p":"Quando esperou por compaixão, o salmista encontrou consoladores.","c":false,"v":20,"e":"No versículo 20, ele diz que esperou por compaixão e por consoladores, mas não os achou."},
 {"t":"cv","p":"Na sua sede, ofereceram vinagre ao salmista para beber.","c":true,"v":21,"e":"No versículo 21, ele diz que, na sua sede, lhe ofereceram vinagre para beber."},
 {"t":"cv","p":"O salmo termina dizendo que Deus salvará Sião e restaurará as cidades de Judá.","c":true,"v":35,"e":"No versículo 35, está escrito que Deus salvará Sião e restaurará as cidades de Judá."}
]}

Salmos 60 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Logo no início, o que o salmista diz que Deus fez com o povo?","o":["Rejeitou e dispersou","Abençoou e multiplicou","Libertou do Egito","Guardou no deserto"],"c":0,"v":1,"e":"No versículo 1 o salmista diz: 'Ó Deus, tu nos rejeitaste e nos dispersaste'."},
 {"t":"multipla","p":"Que vinho Deus fez o povo beber?","o":["O vinho da alegria","O vinho da confusão","O vinho novo","O vinho da aliança"],"c":1,"v":3,"e":"O versículo 3 diz que Deus os fez 'beber o vinho da confusão'."},
 {"t":"multipla","p":"O que Deus deu aos que o temem?","o":["Uma espada","Uma coroa","Um estandarte","Um escudo"],"c":2,"v":4,"e":"O versículo 4 diz: 'Deste um estandarte aos que te temem'."},
 {"t":"multipla","p":"Quando Deus fala na sua santidade, o que diz que vai repartir e medir?","o":["Jerusalém e o vale de Hinom","Betel e o vale de Acor","Hebrom e o vale de Escol","Siquém e o vale de Sucote"],"c":3,"v":6,"e":"No versículo 6 Deus diz: 'repartirei a Siquém e medirei o vale de Sucote'."},
 {"t":"multipla","p":"O que Moabe é para Deus, segundo o salmo?","o":["A sua bacia de lavar","O seu cetro","A defesa da sua cabeça","O lugar do seu sapato"],"c":0,"v":8,"e":"O versículo 8 diz: 'Moabe, porém, é a minha bacia de lavar'."},
 {"t":"cv","p":"Deus diz que Judá é o seu cetro.","c":true,"v":7,"e":"O versículo 7 termina com 'Judá é meu cetro'."},
 {"t":"cv","p":"O salmista pergunta quem o guiará até Moabe.","c":false,"v":9,"e":"No versículo 9 a pergunta é 'Quem me guiará até Edom?', e não até Moabe."},
 {"t":"cv","p":"O salmo termina dizendo que o povo vencerá pela força dos próprios exércitos.","c":false,"v":12,"e":"O versículo 12 diz que 'em Deus' farão proezas, pois é Ele quem calca aos pés os adversários."}
]}

Salmos 62 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Segundo o salmista, de onde vem a sua salvação?","o":["Dos reis da terra","Somente de Deus","Das suas riquezas","Da força do seu braço"],"c":1,"v":1,"e":"Logo no início o salmista diz que espera somente em Deus, porque dele vem a sua salvação."},
 {"t":"multipla","p":"Com o que o salmista compara os que tramam o mal contra um homem?","o":["Com a palha levada pelo vento","Com uma árvore sem raiz","Com uma parede inclinada ou um muro prestes a cair","Com uma casa construída sobre a areia"],"c":2,"v":3,"e":"Ao falar dos que tramam o mal, o salmista pergunta se não serão como uma parede inclinada ou um muro prestes a cair."},
 {"t":"multipla","p":"Como agem os inimigos com a boca e no íntimo?","o":["Com a boca louvam, mas no íntimo amaldiçoam","Com a boca amaldiçoam, mas no íntimo louvam","Com a boca choram, mas no íntimo se alegram","Com a boca calam, mas no íntimo tramam"],"c":0,"v":4,"e":"O salmista diz que eles se regozijam em mentiras e que com a boca louvam, mas no íntimo amaldiçoam."},
 {"t":"multipla","p":"O que o povo é chamado a derramar diante de Deus?","o":["As suas lágrimas","As suas ofertas","O seu sangue","O seu coração"],"c":3,"v":8,"e":"O salmista convida o povo a confiar em Deus em todo tempo e a derramar diante dele o coração."},
 {"t":"multipla","p":"Pesados em balanças, os homens são mais leves do que o quê?","o":["Uma pena","A vaidade","O pó da terra","A fumaça"],"c":1,"v":9,"e":"O salmista diz que, pesados em balanças, os homens juntos são mais leves do que a vaidade."},
 {"t":"cv","p":"O salmista aconselha pôr o coração nas riquezas quando elas prosperam.","c":false,"v":10,"e":"O salmista diz o contrário: se as riquezas prosperam, não se deve pôr nelas o coração."},
 {"t":"cv","p":"O salmista diz ter ouvido que o poder pertence a Deus.","c":true,"v":11,"e":"O salmista diz que Deus falou uma vez, e duas vezes ele ouviu que o poder pertence a Deus."},
 {"t":"cv","p":"O salmo termina dizendo que o Senhor retribuirá a cada um segundo as suas obras.","c":true,"v":12,"e":"No fim do salmo está escrito que ao Senhor pertence a graça, pois ele retribuirá a cada um segundo as suas obras."}
]}

Salmos 43 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Contra quem o salmista pede que Deus defenda a sua causa?","o":["A nação contenciosa","Os sacerdotes do templo","Os filisteus","Os seus próprios irmãos"],"c":0,"v":1,"e":"No versículo 1, ele pede que Deus pleiteie a sua causa contra a nação contenciosa."},
 {"t":"multipla","p":"De quem o salmista pede para ser livrado?","o":["Do leão e do urso","Do homem fraudulento e injusto","Da espada do rei","Da doença e da morte"],"c":1,"v":1,"e":"No versículo 1, ele pede: livra-me do homem fraudulento e injusto."},
 {"t":"multipla","p":"Como o salmista chama Deus ao perguntar por que é rejeitado?","o":["O Deus dos exércitos","O Deus de Jacó","O Deus da minha fortaleza","O Deus do céu"],"c":2,"v":2,"e":"No versículo 2, ele diz: tu és o Deus da minha fortaleza; por que me rejeitas?"},
 {"t":"multipla","p":"O que o salmista pede que o guie até o santo monte de Deus?","o":["A nuvem e o fogo","Um anjo e uma estrela","A lei e os profetas","A luz e a verdade"],"c":3,"v":3,"e":"No versículo 3, ele pede a luz e a verdade para que o guiem ao santo monte e às habitações de Deus."},
 {"t":"multipla","p":"Ao som de qual instrumento o salmista diz que louvará a Deus?","o":["Harpa","Trombeta","Flauta","Címbalo"],"c":0,"v":4,"e":"No versículo 4, ele diz: ao som da harpa, te louvarei, ó Deus."},
 {"t":"cv","p":"O salmista diz que anda lamentando sob a opressão dos seus inimigos.","c":true,"v":2,"e":"No versículo 2, ele pergunta: por que ando lamentando sob a opressão dos meus inimigos?"},
 {"t":"cv","p":"O salmista diz que irá ao altar de Deus, a quem chama de sua grande alegria.","c":true,"v":4,"e":"No versículo 4, ele diz: irei ao altar de Deus, Deus que é a minha grande alegria."},
 {"t":"cv","p":"No fim do salmo, o salmista diz à sua alma que pare de esperar em Deus.","c":false,"v":5,"e":"No versículo 5, ele diz o contrário: espere em Deus, pois ainda o louvarei."}
]}

Salmos 75 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Por que o salmista rende graças a Deus no início do salmo?","o":["Porque o nome de Deus está próximo","Porque venceu uma batalha","Porque recebeu uma boa colheita","Porque foi curado de uma doença"],"c":0,"v":1,"e":"No versículo 1, o salmista rende graças \"pois o teu nome está próximo\"."},
 {"t":"multipla","p":"Quando ocupar o tempo determinado, como Deus diz que julgará?","o":["Com ira","Com justiça","Em segredo","Com pressa"],"c":1,"v":2,"e":"No versículo 2, Deus diz: \"julgarei com justiça\"."},
 {"t":"multipla","p":"A terra e seus habitantes estão vacilando. O que Deus diz que fará?","o":["Abalará os montes","Enviará chuva sobre a terra","Firmará as suas colunas","Fechará os céus"],"c":2,"v":3,"e":"No versículo 3, Deus diz: \"eu firmarei as suas colunas\"."},
 {"t":"multipla","p":"Contra quem os arrogantes não devem falar com insolência?","o":["Contra o rei","Contra os sacerdotes","Contra o próximo","Contra a Rocha"],"c":3,"v":5,"e":"O versículo 5 manda não falar com insolência \"contra a Rocha\"."},
 {"t":"multipla","p":"O que há na mão do Senhor, segundo o salmo?","o":["Uma espada afiada","Um cálice cujo vinho espuma","Um cetro de ferro","Uma balança"],"c":1,"v":8,"e":"O versículo 8 diz que na mão do Senhor há um cálice cujo vinho espuma, e os ímpios o bebem até as escórias."},
 {"t":"cv","p":"O salmo afirma que Deus é o Juiz, que a um derruba e a outro exalta.","c":true,"v":7,"e":"O versículo 7 diz: \"Deus é o Juiz; a um derruba mas a outro exalta\"."},
 {"t":"cv","p":"O salmista diz que salmodiará louvores ao Deus de Abraão.","c":false,"v":9,"e":"No versículo 9, os louvores são ao \"Deus de Jacó\"."},
 {"t":"cv","p":"O salmo termina dizendo que a força dos justos será exaltada.","c":true,"v":10,"e":"O versículo 10 diz que as forças dos ímpios serão desmanteladas, mas a força dos justos será exaltada."}
]}

Salmos 64 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que o salmista pede que Deus preserve do terror do inimigo?","o":["A sua vida","A sua casa","O seu povo","A sua honra"],"c":0,"v":1,"e":"No versículo 1, o salmista pede: \"preserva a minha vida do terror do inimigo\"."},
 {"t":"multipla","p":"Os ímpios afiavam suas línguas como o quê?","o":["Lanças","Navalhas","Espadas","Pedras"],"c":2,"v":3,"e":"O versículo 3 diz que eles \"afiavam suas línguas como espadas\"."},
 {"t":"multipla","p":"O que os ímpios dizem enquanto tramam armadilhas em secreto?","o":["Deus não nos ouve","Quem nos verá?","Ninguém escapará","Vamos à guerra"],"c":1,"v":5,"e":"No versículo 5, eles tramam armadilhas em secreto e dizem: \"Quem nos verá?\"."},
 {"t":"multipla","p":"O que Deus lançará contra os ímpios?","o":["Fogo do céu","Uma grande pedra","A espada","Uma seta"],"c":3,"v":7,"e":"O versículo 7 diz que \"Deus lançará contra eles uma seta\"."},
 {"t":"multipla","p":"O que se voltará contra os próprios ímpios?","o":["Suas próprias línguas","Seus próprios filhos","Suas próprias armas","Seus próprios amigos"],"c":0,"v":8,"e":"O versículo 8 diz que \"suas próprias línguas se voltarão contra eles\"."},
 {"t":"cv","p":"Os ímpios atacam o íntegro abertamente, à vista de todos.","c":false,"v":4,"e":"O versículo 4 diz que eles agem \"para emboscar secretamente o íntegro\"."},
 {"t":"cv","p":"Todos os homens temerão e anunciarão as obras de Deus.","c":true,"v":9,"e":"O versículo 9 diz que \"todos os homens temerão, anunciarão as obras de Deus\"."},
 {"t":"cv","p":"O justo se alegra no Senhor e confia nele.","c":true,"v":10,"e":"O versículo 10 diz: \"O justo se alegra no Senhor e confia nele\"."}
]}

Salmos 63 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Em que tipo de terra o corpo do salmista anseia por Deus?","o":["Terra seca e exausta, onde não há água","Terra fértil, cheia de rios","Terra de montes cobertos de neve","Terra de vales e pastos verdes"],"c":0,"v":1,"e":"No versículo 1 o salmista diz que seu corpo anseia por Deus em uma terra seca e exausta, onde não há água."},
 {"t":"multipla","p":"Para que o salmista contempla Deus no santuário?","o":["Para oferecer sacrifícios","Para pedir vitória na guerra","Para ver o seu poder e a sua glória","Para ouvir os sacerdotes"],"c":2,"v":2,"e":"O versículo 2 diz que ele contempla Deus no santuário para ver o seu poder e a sua glória."},
 {"t":"multipla","p":"Segundo o salmista, a graça de Deus é melhor do que o quê?","o":["O ouro","A vida","O vinho","A sabedoria"],"c":1,"v":3,"e":"O versículo 3 afirma que a graça de Deus é melhor do que a vida."},
 {"t":"multipla","p":"Quando o salmista se recorda de Deus e medita nele?","o":["Ao meio-dia, no templo","No campo de batalha","À mesa, nas festas","No leito, durante as vigílias da noite"],"c":3,"v":6,"e":"No versículo 6 ele se recorda de Deus no leito e medita nele durante as vigílias da noite."},
 {"t":"multipla","p":"Os que buscam a vida do salmista se tornarão pasto para quais animais?","o":["Os leões","Os abutres","Os chacais","Os lobos"],"c":2,"v":10,"e":"O versículo 10 diz que eles cairão sob a espada e se tornarão pasto para os chacais."},
 {"t":"cv","p":"O salmista diz que sua alma ficará faminta e sem consolo.","c":false,"v":5,"e":"No versículo 5 ele diz o contrário: sua alma será saciada como de banha e com a gordura mais abundante."},
 {"t":"cv","p":"O salmista canta jubiloso à sombra das asas de Deus.","c":true,"v":7,"e":"O versículo 7 diz que Deus tem sido o seu auxílio e que à sombra das suas asas ele canta jubiloso."},
 {"t":"cv","p":"No fim do salmo, os que proferem mentiras ficarão emudecidos.","c":true,"v":11,"e":"O versículo 11 termina dizendo que ficarão emudecidos os que proferem mentiras."}
]}

Salmos 52 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"De que se gloria o \"homem poderoso\"?","o":["Da maldade","Da sua força","Da sua sabedoria","Da sua fama"],"c":0,"v":1,"e":"No versículo 1, o salmista pergunta: \"Por que te glorias na maldade, ó homem poderoso?\""},
 {"t":"multipla","p":"A língua do praticante de enganos é comparada a quê?","o":["Uma flecha","Uma lâmina afiada","Uma serpente","Um fogo"],"c":1,"v":2,"e":"O versículo 2 diz que a língua trama destruição \"como uma lâmina afiada\"."},
 {"t":"multipla","p":"Segundo o salmo, o homem ama a mentira mais do que o quê?","o":["A justiça","A paz","A verdade","A misericórdia"],"c":2,"v":3,"e":"O versículo 3 diz que ele ama \"a mentira mais do que a verdade\"."},
 {"t":"multipla","p":"De onde Deus arrancará o homem perverso?","o":["Do seu palácio","Da cidade","Do templo","Da sua tenda"],"c":3,"v":5,"e":"O versículo 5 diz que Deus \"te arrancará da tua tenda\"."},
 {"t":"multipla","p":"Com o que o salmista se compara na casa de Deus?","o":["Uma oliveira verdejante","Um cedro do Líbano","Uma videira frutífera","Uma palmeira"],"c":0,"v":8,"e":"No versículo 8 ele diz: \"eu sou como a oliveira verdejante na casa de Deus\"."},
 {"t":"cv","p":"Ao verem o castigo do perverso, os justos choram por ele.","c":false,"v":6,"e":"O versículo 6 diz que os justos \"temerão e se rirão dele\", e não que choram por ele."},
 {"t":"cv","p":"O homem castigado não pôs em Deus a sua fortaleza, mas confiou na abundância dos seus bens.","c":true,"v":7,"e":"É exatamente o que os justos dizem dele no versículo 7."},
 {"t":"cv","p":"O salmista diz que esperará no nome de Deus na presença dos seus fiéis.","c":true,"v":9,"e":"No versículo 9 ele diz: \"na presença dos teus fiéis, esperarei no teu nome, pois é bom\"."}
]}

Salmos 45 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"No início do salmo, o salmista compara a sua língua a quê?","o":["A uma espada afiada","À pena de habilidoso escritor","A uma harpa bem afinada","A uma fonte de água viva"],"c":1,"v":1,"e":"No versículo 1, o salmista diz que a sua língua é como a pena de habilidoso escritor."},
 {"t":"multipla","p":"Por qual causa o cavaleiro é chamado a avançar com vigor?","o":["Pela causa da vingança e da guerra","Pela causa da riqueza e da glória","Pela causa da verdade e da justiça","Pela causa da paz e do perdão"],"c":2,"v":4,"e":"O versículo 4 manda o cavaleiro avançar pela causa da verdade e da justiça."},
 {"t":"multipla","p":"Segundo o salmo, por que Deus ungiu o rei com o óleo de alegria?","o":["Porque ele ama a justiça e odeia a iniquidade","Porque ele venceu muitas batalhas","Porque ele construiu palácios de marfim","Porque ele era o filho mais velho"],"c":0,"v":7,"e":"O versículo 7 diz que o rei ama a justiça e odeia a iniquidade, e por isso Deus o ungiu."},
 {"t":"multipla","p":"De onde vem o ouro finíssimo que adorna a rainha à direita do rei?","o":["De Társis","De Ofir","De Sabá","Do Egito"],"c":1,"v":9,"e":"O versículo 9 diz que a rainha está adornada com o ouro finíssimo de Ofir."},
 {"t":"multipla","p":"Quem virá trazendo donativos?","o":["A rainha de Sabá","Os reis de Társis","A filha de Tiro","A filha de Babilônia"],"c":2,"v":12,"e":"O versículo 12 diz que a filha de Tiro virá trazendo donativos."},
 {"t":"cv","p":"A filha é chamada a esquecer o seu povo e a casa de seu pai.","c":true,"v":10,"e":"O versículo 10 diz: esqueça seu povo e a casa de seu pai."},
 {"t":"cv","p":"A filha do rei é levada à presença do rei por soldados armados.","c":false,"v":14,"e":"O versículo 14 diz que são as suas companheiras, as virgens, que a levam ao rei."},
 {"t":"cv","p":"No final do salmo, o salmista diz que fará o nome do rei ser celebrado de geração em geração.","c":true,"v":17,"e":"O versículo 17 diz: farei com que o teu nome seja celebrado de geração em geração."}
]}

Salmos 54 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Por meio de que o salmista pede que Deus o salve?","o":["Pelo teu nome","Pela tua lei","Pelo teu templo","Pela tua aliança"],"c":0,"v":1,"e":"No versículo 1 ele diz: \"Salva-me, ó Deus, pelo teu nome\"."},
 {"t":"multipla","p":"O que o salmista pede que Deus escute?","o":["O seu choro","A sua oração","O seu cântico","O seu voto"],"c":1,"v":2,"e":"No versículo 2 ele pede: \"Ó Deus, escuta a minha oração\"."},
 {"t":"multipla","p":"O que os violentos buscam fazer contra o salmista?","o":["Tomar a sua casa","Tirar-lhe a vida","Roubar o seu rebanho","Expulsá-lo da cidade"],"c":1,"v":3,"e":"O versículo 3 diz que \"os violentos buscam tirar-me a vida\"."},
 {"t":"multipla","p":"Como o salmista chama Deus no versículo 4?","o":["O meu pastor","O meu rochedo","O meu ajudador","O meu escudo"],"c":2,"v":4,"e":"No versículo 4 ele declara: \"Eis que Deus é o meu ajudador\"."},
 {"t":"multipla","p":"O que o salmista promete oferecer a Deus?","o":["Ofertas de cereais","Sacrifícios, de forma voluntária","O dízimo de tudo","Incenso no altar"],"c":1,"v":6,"e":"No versículo 6 ele diz: \"Oferecerei de forma voluntária sacrifícios\"."},
 {"t":"cv","p":"O salmista diz que os insolentes não têm Deus diante de si.","c":true,"v":3,"e":"O versículo 3 diz dos insolentes e violentos: \"não têm Deus diante de si\"."},
 {"t":"cv","p":"O salmista diz que ele mesmo vai se vingar dos que o espreitam.","c":false,"v":5,"e":"O versículo 5 diz que é Deus quem \"retribuirá o mal àqueles que me espreitam\"."},
 {"t":"cv","p":"No fim do salmo, o salmista diz que Deus o livrou de toda a tribulação.","c":true,"v":7,"e":"O versículo 7 diz: \"Pois Ele me livrou de toda a tribulação\"."}
]}

Salmos 58 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"No início do salmo, a quem Davi pergunta se falam verdadeiramente a justiça?","o":["Aos juízes","Aos sacerdotes","Aos reis","Aos profetas"],"c":0,"v":1,"e":"O versículo 1 pergunta: \"Falais verdadeiramente a justiça, ó juízes?\""},
 {"t":"multipla","p":"Segundo o salmo, o que eles tramam no coração?","o":["A paz","A iniquidade","A fuga","O perdão"],"c":1,"v":2,"e":"O versículo 2 diz que no coração eles tramam a iniquidade na terra."},
 {"t":"multipla","p":"A que é comparado o veneno dos ímpios?","o":["Ao de um escorpião","Ao de uma planta","Ao de uma serpente","Ao de uma aranha"],"c":2,"v":4,"e":"O versículo 4 diz que o veneno deles é similar ao veneno de uma serpente."},
 {"t":"multipla","p":"Por que a víbora surda fecha os ouvidos?","o":["Para não ouvir o trovão","Para não ouvir o rugido dos leões","Para não ouvir os juízes","Para não ouvir a voz dos encantadores"],"c":3,"v":5,"e":"O versículo 5 diz que ela fecha os ouvidos para não ouvir a voz dos encantadores."},
 {"t":"multipla","p":"O que o salmista pede que Deus quebre na boca dos ímpios?","o":["As armas","Os dentes","As línguas","Os lábios"],"c":1,"v":6,"e":"O versículo 6 pede: \"Ó Deus, quebra-lhes os dentes na boca\"."},
